334			t.Fatalf("核对中的被拒绝记录应保持原编号、要求、依据与原因，得到 %+v", rj)
335		}
336	
337		// 同编号换要求或换依据：按内容冲突拒绝，原申请与原核对结果不变。
338		mustCourse(t, s, "c2", "物理", 3)
339		mustReq(t, s, "s1", "r2", "c2")
340		if _, _, err := s.ApplyWaiver("s1", "r2", "w1", "学科竞赛获奖"); err == nil {
341			t.Fatal("已拒绝申请同编号换要求应被拒绝")
342		}
343		if _, _, err := s.ApplyWaiver("s1", "r1", "w1", "另一份依据"); err == nil {
344			t.Fatal("已拒绝申请同编号换依据应被拒绝")
345		}
346		if got := s.Waiver("s1", "w1"); got.Status != WaiverRejected ||
347			got.ReqID != "r1" || got.Basis != "学科竞赛获奖" || got.Reason != origReason {
348			t.Fatalf("内容冲突不应改动原申请，得到 %+v", got)
349		}
350		if rep := s.CheckStudent("s1"); rep.TotalCredits != 0 || len(rep.RejectedWaivers) != 1 {
351			t.Fatalf("内容冲突不应改变原核对结果，得到学分=%d 被拒绝=%d",
352				rep.TotalCredits, len(rep.RejectedWaivers))
353		}
354	
355		// 目标补建后，用新编号正常申请免修的既有行为不变。
356		w3, a, err := s.ApplyWaiver("s1", "r1", "w2", "外校同层次课程")
357		if err != nil || a != ActionCreated || w3.Status != WaiverApproved {
358			t.Fatalf("补建要求后新编号申请应正常生效，得到 %+v action=%v err=%v", w3, a, err)
359		}
360		rep = s.CheckStudent("s1")
361		if rep.TotalCredits != 4 || len(rep.Unmet) != 1 || rep.Unmet[0] != "r2" {
362			t.Fatalf("新免修应正常计学分，得到学分=%d 未满足=%v", rep.TotalCredits, rep.Unmet)
363		}
364		if len(rep.RejectedWaivers) != 1 || rep.RejectedWaivers[0].Waiver.ID != "w1" {
365			t.Fatalf("旧拒绝记录应继续保留，得到 %+v", rep.RejectedWaivers)
366		}
367	}
