269		runCLI(t, file, "course", "c1", "数学", "4")
270		if _, errText, code := runCLI(t, file, "req", "ghost", "r1", "c1"); code == 0 {
271			t.Fatalf("引用不存在学生应拒绝，err=%q", errText)
272		}
273		if _, errText, code := runCLI(t, file, "enroll", "s1", "r1", "2024春", "e1"); code == 0 {
274			t.Fatalf("引用不存在要求应拒绝，err=%q", errText)
275		}
