345	// setupCLISharedEnrollments 建立两名学生就同一门 4 学分课程的同号要求 r1 与
346	// 同一学期的同号修读 e1，并断言两份修读都成功登记、初始为选课、各自核对均为
347	// 0 学分且要求未满足。
348	func setupCLISharedEnrollments(t *testing.T, file string) {
349		t.Helper()
350		for _, st := range [][]string{
351			{"student", "s1"},
352			{"student", "s2"},
353			{"course", "c1", "高等数学", "4"},
354			{"req", "s1", "r1", "c1"},
355			{"req", "s2", "r1", "c1"},
356			{"enroll", "s1", "r1", "2024春", "e1"},
357			{"enroll", "s2", "r1", "2024春", "e1"},
358		} {
359			if _, errText, code := runCLI(t, file, st...); code != 0 {
360				t.Fatalf("步骤 %v 应成功，code=%d err=%q", st, code, errText)
361			}
362		}
363		for _, student := range []string{"s1", "s2"} {
364			out, _, code := runCLI(t, file, "show", student)
365			if code != 0 || !strings.Contains(out, "修读 e1：要求 r1，学期 2024春，结果：选课") {
366				t.Fatalf("学生 %s 的同号修读应已登记且初始为选课，code=%d out=%q",
367					student, code, out)
368			}
369			out, _, code = runCLI(t, file, "check", student)
370			if code != 0 || !strings.Contains(out, "总学分：0") ||
371				!strings.Contains(out, "未满足要求：[r1]") {
372				t.Fatalf("学生 %s 初始核对应为 0 学分且要求未满足，code=%d out=%q",
373					student, code, out)
374			}
375		}
376	}
