378	// TestCLISharedEnrollmentResultOwnership 两名学生共享要求编号与修读编号时，
379	// 命令行提交结果必须各归各：s1 通过只影响 s1，s2 随后未通过只影响 s2。
380	func TestCLISharedEnrollmentResultOwnership(t *testing.T) {
381		file := filepath.Join(t.TempDir(), "records.json")
382		setupCLISharedEnrollments(t, file)
383	
384		// s1 提交通过：退出码 0，只有 s1 获得 4 学分、要求满足、来源是本人的 e1。
385		if _, errText, code := runCLI(t, file, "pass", "s1", "e1"); code != 0 {
386			t.Fatalf("s1 首次提交通过应成功且退出码 0，code=%d err=%q", code, errText)
387		}
388		out, _, code := runCLI(t, file, "check", "s1")
389		if code != 0 || !strings.Contains(out, "总学分：4") ||
390			!strings.Contains(out, "要求 r1") || !strings.Contains(out, "已满足") ||
391			!strings.Contains(out, "来源为通过修读 e1") {
392			t.Fatalf("s1 应得 4 学分且要求由本人 e1 满足，code=%d out=%q", code, out)
393		}
394		if strings.Contains(out, "未满足要求：[") {
395			t.Fatalf("s1 不应再有未满足要求，out=%q", out)
396		}
397		// s2 仍是选课：不能因为编号相同拿到学分或被改成通过。
398		out, _, code = runCLI(t, file, "check", "s2")
399		if code != 0 || !strings.Contains(out, "总学分：0") ||
400			!strings.Contains(out, "未满足要求：[r1]") || strings.Contains(out, "通过修读") {
401			t.Fatalf("s2 不应因 s1 的同号通过拿到学分，code=%d out=%q", code, out)
402		}
403		if out, _, _ := runCLI(t, file, "show", "s2"); !strings.Contains(out, "结果：选课") {
404			t.Fatalf("s2 的同号修读应保持选课，out=%q", out)
405		}
406	
407		// s2 随后提交未通过：退出码 0，s2 仍为 0 学分、要求未满足。
408		if _, errText, code := runCLI(t, file, "fail", "s2", "e1"); code != 0 {
409			t.Fatalf("s2 首次提交未通过应成功且退出码 0，code=%d err=%q", code, errText)
410		}
411		out, _, code = runCLI(t, file, "check", "s2")
412		if code != 0 || !strings.Contains(out, "总学分：0") ||
413			!strings.Contains(out, "未满足要求：[r1]") {
414			t.Fatalf("s2 未通过后应仍为 0 学分且要求未满足，code=%d out=%q", code, out)
415		}
416		if out, _, _ := runCLI(t, file, "show", "s2"); !strings.Contains(out, "结果：未通过") {
417			t.Fatalf("s2 的修读应记录为未通过，out=%q", out)
418		}
419		// s1 原来的通过结果、学分与来源均保持不变。
420		out, _, code = runCLI(t, file, "check", "s1")
421		if code != 0 || !strings.Contains(out, "总学分：4") ||
422			!strings.Contains(out, "来源为通过修读 e1") {
423			t.Fatalf("s2 提交未通过不应影响 s1 原有的通过结果，code=%d out=%q", code, out)
424		}
425		if out, _, _ := runCLI(t, file, "show", "s1"); !strings.Contains(out, "结果：通过") {
426			t.Fatalf("s1 的修读应保持通过，out=%q", out)
427		}
428	
429		// 两人结果不同应分别被接受：各自重复提交相同结果幂等成功（退出码 0），
430		// 不能被误判为同一次修读的结果冲突；状态不变。
431		if _, errText, code := runCLI(t, file, "pass", "s1", "e1"); code != 0 {
432			t.Fatalf("s1 重复提交通过应幂等成功，code=%d err=%q", code, errText)
433		}
434		if _, errText, code := runCLI(t, file, "fail", "s2", "e1"); code != 0 {
435			t.Fatalf("s2 重复提交未通过应幂等成功，code=%d err=%q", code, errText)
436		}
437		out, _, _ = runCLI(t, file, "check", "s1")
438		if !strings.Contains(out, "总学分：4") || !strings.Contains(out, "来源为通过修读 e1") {
439			t.Fatalf("幂等重复后 s1 结果应不变，out=%q", out)
440		}
441		out, _, _ = runCLI(t, file, "check", "s2")
442		if !strings.Contains(out, "总学分：0") || !strings.Contains(out, "未满足要求：[r1]") {
443			t.Fatalf("幂等重复后 s2 结果应不变，out=%q", out)
444		}
445	
446		// 各自把本人这份修读改成另一结果：仍按现有规则拒绝（退出码 1）、保留原结果，
447		// 另一名学生的同号修读保持原样。
448		if _, errText, code := runCLI(t, file, "fail", "s1", "e1"); code != 1 {
449			t.Fatalf("s1 通过后改提未通过应拒绝且退出码 1，code=%d err=%q", code, errText)
450		}
451		if _, errText, code := runCLI(t, file, "pass", "s2", "e1"); code != 1 {
452			t.Fatalf("s2 未通过后改提通过应拒绝且退出码 1，code=%d err=%q", code, errText)
453		}
454		if out, _, _ := runCLI(t, file, "show", "s1"); !strings.Contains(out, "结果：通过") {
455			t.Fatalf("被拒绝后 s1 应保留原通过结果，out=%q", out)
456		}
457		if out, _, _ := runCLI(t, file, "show", "s2"); !strings.Contains(out, "结果：未通过") {
458			t.Fatalf("被拒绝后 s2 应保留原未通过结果，out=%q", out)
459		}
460		out, _, _ = runCLI(t, file, "check", "s1")
461		if !strings.Contains(out, "总学分：4") || !strings.Contains(out, "来源为通过修读 e1") {
462			t.Fatalf("改结果被拒后 s1 学分与来源应不变，out=%q", out)
463		}
464		out, _, _ = runCLI(t, file, "check", "s2")
465		if !strings.Contains(out, "总学分：0") || !strings.Contains(out, "未满足要求：[r1]") {
466			t.Fatalf("改结果被拒后 s2 应仍为 0 学分未满足，out=%q", out)
467		}
468	}
469	
470	// TestCLISharedEnrollmentResultOwnershipReversed 交换两名学生的登记与处理顺序：
471	// 先 s2 未通过、再 s1 通过，归属结论必须一致，不依赖先登记或先处理谁。
472	func TestCLISharedEnrollmentResultOwnershipReversed(t *testing.T) {
473		file := filepath.Join(t.TempDir(), "records.json")
474		// 先登记 s2，再登记 s1。
475		for _, st := range [][]string{
476			{"student", "s2"},
477			{"student", "s1"},
478			{"course", "c1", "高等数学", "4"},
479			{"req", "s2", "r1", "c1"},
480			{"req", "s1", "r1", "c1"},
481			{"enroll", "s2", "r1", "2024春", "e1"},
482			{"enroll", "s1", "r1", "2024春", "e1"},
483		} {
484			if _, errText, code := runCLI(t, file, st...); code != 0 {
485				t.Fatalf("步骤 %v 应成功，code=%d err=%q", st, code, errText)
486			}
487		}
488	
489		if _, _, code := runCLI(t, file, "fail", "s2", "e1"); code != 0 {
490			t.Fatal("先处理的 s2 提交未通过应成功")
491		}
492		if _, _, code := runCLI(t, file, "pass", "s1", "e1"); code != 0 {
493			t.Fatal("后处理的 s1 提交通过应成功")
494		}
495	
496		out, _, code := runCLI(t, file, "check", "s1")
497		if code != 0 || !strings.Contains(out, "总学分：4") ||
498			!strings.Contains(out, "来源为通过修读 e1") {
499			t.Fatalf("s1 应由本人 e1 通过获得 4 学分，code=%d out=%q", code, out)
500		}
501		if out, _, _ := runCLI(t, file, "show", "s1"); !strings.Contains(out, "结果：通过") {
502			t.Fatalf("s1 的修读应为通过，out=%q", out)
503		}
504		out, _, code = runCLI(t, file, "check", "s2")
505		if code != 0 || !strings.Contains(out, "总学分：0") ||
506			!strings.Contains(out, "未满足要求：[r1]") {
507			t.Fatalf("s2 应仍为 0 学分且要求未满足，code=%d out=%q", code, out)
508		}
509		if out, _, _ := runCLI(t, file, "show", "s2"); !strings.Contains(out, "结果：未通过") {
510			t.Fatalf("s2 的修读应为未通过，out=%q", out)
511		}
512	}
513	
514	// TestCLISubmitResultUnknownEnrollmentUnderOtherStudent 修读编号只存在于 s1 名下时，
515	// 用 s2 的名义提交结果必须明确报告 s2 名下没有该修读、退出码 1，不能借用 s1 的
516	// 修读，也不能为 s2 补出新记录；拒绝后两人的状态、要求与总学分与提交前一致，
517	// 记录文件也不应被这次拒绝改写。
518	func TestCLISubmitResultUnknownEnrollmentUnderOtherStudent(t *testing.T) {
519		file := filepath.Join(t.TempDir(), "records.json")
520		for _, st := range [][]string{
521			{"student", "s1"},
522			{"student", "s2"},
523			{"course", "c1", "高等数学", "4"},
524			{"req", "s1", "r1", "c1"},
525			{"enroll", "s1", "r1", "2024春", "e1"},
526		} {
527			if _, errText, code := runCLI(t, file, st...); code != 0 {
528				t.Fatalf("步骤 %v 应成功，code=%d err=%q", st, code, errText)
529			}
530		}
531		before, err := os.ReadFile(file)
532		if err != nil {
533			t.Fatal(err)
534		}
535	
536		// 用 s2 的编号提交只属于 s1 的修读结果：退出码 1，信息点名 s2 与 e1。
537		out, errText, code := runCLI(t, file, "pass", "s2", "e1")
538		if code != 1 {
539			t.Fatalf("借名提交应拒绝且退出码 1，code=%d out=%q err=%q", code, out, errText)
540		}
541		if !strings.Contains(errText, "s2") || !strings.Contains(errText, "e1") ||
542			!strings.Contains(errText, "不存在") {
543			t.Fatalf("应明确报告学生 s2 名下不存在修读 e1，out=%q err=%q", out, errText)
544		}
545	
546		// 被拒绝的请求不应改写记录文件。
547		after, err := os.ReadFile(file)
548		if err != nil {
549			t.Fatal(err)
550		}
551		if string(before) != string(after) {
552			t.Fatalf("拒绝后记录文件不应变化\nbefore=%s\nafter=%s", before, after)
553		}
554	
555		// 不能借用 s1 的修读：s1 的 e1 仍是选课、0 学分、要求未满足。
556		if out, _, _ := runCLI(t, file, "show", "s1"); !strings.Contains(out, "结果：选课") {
557			t.Fatalf("s1 的修读不应被借名提交改写，out=%q", out)
558		}
559		out, _, code = runCLI(t, file, "check", "s1")
560		if code != 0 || !strings.Contains(out, "总学分：0") ||
561			!strings.Contains(out, "未满足要求：[r1]") {
562			t.Fatalf("s1 拒绝后应与提交前一致（0 学分未满足），code=%d out=%q", code, out)
563		}
564		// 不能为 s2 补出一条新记录：show 中没有任何修读，核对总学分 0。
565		if out, _, _ := runCLI(t, file, "show", "s2"); strings.Contains(out, "修读 e1") {
566			t.Fatalf("不应在 s2 名下补出修读记录，out=%q", out)
567		}
568		out, _, code = runCLI(t, file, "check", "s2")
569		if code != 0 || !strings.Contains(out, "总学分：0") {
570			t.Fatalf("s2 不应因拒绝产生任何变化，code=%d out=%q", code, out)
571		}
572	}
